// 封装和token相关的方法 存 取 删

const TOKENKEY = 'token-key'
const setToken = token => {
    localStorage.setItem(TOKENKEY, token)
}

const getToken = token => {
    return localStorage.getItem(TOKENKEY)
}

const removeToken = token => {
    localStorage.removeItem(TOKENKEY)
}

export {
    setToken,
    getToken,
    removeToken
}